using System.Windows;
using System.Windows.Media;
using Occlusa.Shared.Services;

namespace Occlusa.Desktop.Controls;

/// <summary>
/// Immutable GPU-cached vector geometries for a single FDI tooth's anatomical crown, roots,
/// root canals, and implant fixture.
/// Anatomical outline curves adapted from ZoliQua/React-Advanced-Odontogram
/// (MIT License, Copyright (c) 2026 Zoltan Dul).
/// </summary>
public sealed record ToothAnatomyGeometry(
    int ToothNumber,
    bool IsUpperArch,
    bool IsMirroredHorizontally,
    double CanvasWidth,
    double CanvasHeight,
    double CejY,
    Geometry FullSilhouette,
    Geometry CrownCap,
    Geometry RootsOnly,
    Geometry RootCanals,
    Geometry ImplantFixture);

/// <summary>
/// Provides frozen WPF vector geometries for all 52 FDI teeth (Permanent 11-48 and Primary 51-85).
/// </summary>
public static class ToothAnatomyCatalog
{
    private sealed record RawTemplate(
        double Width,
        double Height,
        double CejY,
        string OutlinePath,
        string CanalPath);

    private static readonly Dictionary<int, RawTemplate> RawTemplates = BuildRawTemplates();
    private static readonly Dictionary<int, ToothAnatomyGeometry> Cache = BuildGeometryCache();

    public static IReadOnlyCollection<int> SupportedTeeth => Cache.Keys;

    public static ToothAnatomyGeometry Get(int toothNumber) =>
        Cache.TryGetValue(toothNumber, out var geom) ? geom : Cache[16];

    private static Dictionary<int, ToothAnatomyGeometry> BuildGeometryCache()
    {
        var map = new Dictionary<int, ToothAnatomyGeometry>(OdontogramHelper.AllFdiTeeth.Length);
        foreach (int tooth in OdontogramHelper.AllFdiTeeth)
        {
            int templateKey = ResolveTemplateKey(tooth);
            var tpl = RawTemplates[templateKey];
            bool isUpper = OdontogramHelper.IsUpperTooth(tooth);
            bool mirrorX = ResolveMirrorX(tooth);

            var full = Geometry.Parse(tpl.OutlinePath);
            full.Freeze();

            var crownClip = new RectangleGeometry(new Rect(-8, tpl.CejY, tpl.Width + 16, tpl.Height - tpl.CejY + 12));
            crownClip.Freeze();

            var rootsClip = new RectangleGeometry(new Rect(-8, -4, tpl.Width + 16, tpl.CejY + 4));
            rootsClip.Freeze();

            var crownCap = new CombinedGeometry(GeometryCombineMode.Intersect, full, crownClip);
            crownCap.Freeze();

            var rootsOnly = new CombinedGeometry(GeometryCombineMode.Intersect, full, rootsClip);
            rootsOnly.Freeze();

            var canals = Geometry.Parse(tpl.CanalPath);
            canals.Freeze();

            double midX = tpl.Width * 0.5;
            double screwTop = Math.Max(8.0, tpl.CejY - 30.0);
            double screwBottom = tpl.CejY - 1.5;
            var implant = Geometry.Parse(
                $"M {midX - 5.2:F1},{screwTop:F1} L {midX + 5.2:F1},{screwTop:F1} L {midX + 4.0:F1},{screwBottom:F1} L {midX - 4.0:F1},{screwBottom:F1} Z "
                + $"M {midX - 6.6:F1},{screwTop + 5:F1} L {midX + 6.6:F1},{screwTop + 5:F1} "
                + $"M {midX - 6.3:F1},{screwTop + 11:F1} L {midX + 6.3:F1},{screwTop + 11:F1} "
                + $"M {midX - 5.9:F1},{screwTop + 17:F1} L {midX + 5.9:F1},{screwTop + 17:F1} "
                + $"M {midX - 5.5:F1},{screwTop + 23:F1} L {midX + 5.5:F1},{screwTop + 23:F1}");
            implant.Freeze();

            map[tooth] = new ToothAnatomyGeometry(
                tooth,
                isUpper,
                mirrorX,
                tpl.Width,
                tpl.Height,
                tpl.CejY,
                full,
                crownCap,
                rootsOnly,
                canals,
                implant);
        }

        return map;
    }

    private static int ResolveTemplateKey(int toothNumber)
    {
        int q = toothNumber / 10;
        int pos = toothNumber % 10;
        return q switch
        {
            1 or 2 => 10 + pos,
            3 or 4 => 30 + pos,
            5 or 6 => 50 + pos,
            7 or 8 => 70 + pos,
            _ => 16
        };
    }

    private static bool ResolveMirrorX(int toothNumber)
    {
        int q = toothNumber / 10;
        // Templates 11..18 & 51..55 represent Q1/Q5 (Right), so mirror Q2/Q6.
        // Templates 31..38 & 71..75 represent Q3/Q7 (Left), so mirror Q4/Q8.
        return q is 2 or 6 or 4 or 8;
    }

